import React, { useCallback, useRef, useState, useEffect } from "react";
import { GoogleMap, useLoadScript, Marker, StandaloneSearchBox } from "@react-google-maps/api";

const libraries = ["places"];
const containerStyle = {
  width: "100%",
  height: "300px",
};
const centerDefault = { lat: 20.5937, lng: 78.9629 }; // Center of India or any default coords

export default function MapPicker({ location, onLocationChange }) {
  const { isLoaded, loadError } = useLoadScript({
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY,
    libraries,
  });

  const [markerPosition, setMarkerPosition] = useState(
    location || centerDefault
  );
  const [searchBox, setSearchBox] = useState(null);

  useEffect(() => {
    if (location) {
      setMarkerPosition(location);
    }
  }, [location]);

  const onLoadSearchBox = (ref) => setSearchBox(ref);

  const onPlacesChanged = () => {
    const places = searchBox.getPlaces();
    if (places.length === 0) return;

    const place = places[0];
    if (!place.geometry || !place.geometry.location) return;

    const newLocation = {
      lat: place.geometry.location.lat(),
      lng: place.geometry.location.lng(),
      address: place.formatted_address,
    };
    setMarkerPosition({ lat: newLocation.lat, lng: newLocation.lng });
    onLocationChange(newLocation);
  };

  const onMapClick = (e) => {
    const lat = e.latLng.lat();
    const lng = e.latLng.lng();

    const geocoder = new window.google.maps.Geocoder();
    geocoder.geocode({ location: { lat, lng } }, (results, status) => {
      if (status === "OK" && results[0]) {
        onLocationChange({
          lat,
          lng,
          address: results[0].formatted_address,
        });
        setMarkerPosition({ lat, lng });
      } else {
        alert("Failed to get address for selected location.");
      }
    });
  };

  if (loadError) return <div>Error loading maps</div>;
  if (!isLoaded) return <div>Loading Maps...</div>;

  return (
    <div>
      <StandaloneSearchBox
        onLoad={onLoadSearchBox}
        onPlacesChanged={onPlacesChanged}
      >
        <input
          type="text"
          placeholder="Search location"
          style={{
            boxSizing: "border-box",
            border: "1px solid transparent",
            width: "100%",
            height: "40px",
            padding: "0 12px",
            borderRadius: "4px",
            fontSize: "16px",
            marginBottom: "8px",
            outline: "none",
            textOverflow: "ellipses",
          }}
        />
      </StandaloneSearchBox>

      <GoogleMap
        mapContainerStyle={containerStyle}
        center={markerPosition}
        zoom={15}
        onClick={onMapClick}
      >
        <Marker position={markerPosition} />
      </GoogleMap>
    </div>
  );
}
